"""Camera-guided controller for the single live OvenBroilFish episode.
Uses only the standard client, RGB-D calibration, and robot proprioception.
Commands and observations are logged for the record. No reset or simulator access.
"""
import os,sys,json,time
from pathlib import Path
import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import least_squares
from PIL import Image,ImageDraw
from rcb_client import Robot
ROOT=Path('/app/output'); RUNS=Path('/app/runs')
# Panda manufacturer kinematic chain, in metres.
def trans(xyz):
 t=np.eye(4);t[:3,3]=xyz;return t
def rot(axis,angle):
 t=np.eye(4);t[:3,:3]=Rotation.from_rotvec(np.array(axis)*angle).as_matrix();return t
def fk(q):
 origins=[([0,0,.333],0),([0,0,0],-np.pi/2),([0,-.316,0],np.pi/2),([.0825,0,0],np.pi/2),([-.0825,.384,0],-np.pi/2),([0,0,0],np.pi/2),([.088,0,0],np.pi/2)]
 t=np.eye(4)
 for a,(p,rx) in zip(q,origins): t=t@trans(p)@rot([1,0,0],rx)@rot([0,0,1],a)
 return t

def load_meta(n):return json.loads((RUNS/f'{n:03d}'/'meta.json').read_text())
def pnow(m):return np.array(m['proprio']['now'])
def points(n,cam,pixels):
 m=load_meta(n);c='robot0_'+cam
 dep=np.load(RUNS/f'{n:03d}'/f'depth_{c}.npy');dep=dep[-1] if dep.ndim==3 else dep
 k=np.array(m['cameras'][c]['intrinsic_cv']);t=np.array(m['cameras'][c]['cam2world_gl'])
 out=[]
 for u,v in pixels:
  d=float(dep[v,u]);p=np.array([(u-k[0,2])/k[0,0]*d,-(v-k[1,2])/k[1,1]*d,-d]);out.append((t[:3,:3]@p+t[:3,3]).tolist())
 return out

def montage(n):
 paths=sorted((RUNS/f'{n:03d}'/'last').glob('*.jpg'));out=Image.new('RGB',(640,480))
 for i,p in enumerate(paths):
  im=Image.open(p);ImageDraw.Draw(im).text((3,3),p.stem.replace('robot0_',''),fill='red');out.paste(im,(320*(i%2),240*(i//2)))
 out.save(ROOT/'views.jpg')

class Control:
 def __init__(self):
  self.r=Robot();self.n=max(int(p.name) for p in RUNS.iterdir() if p.name.isdigit());self.m=load_meta(self.n)
  self.cal=None
  if (ROOT/'calib.npz').exists():self.cal=dict(np.load(ROOT/'calib.npz'))
 def save(self,res,cmd):
  self.n+=1;res.save(str(RUNS/f'{self.n:03d}'));self.m=res.meta;montage(self.n)
  with open(ROOT/'commands.jsonl','a') as f:f.write(json.dumps({'run':self.n,'command':cmd})+'\n')
  p=pnow(self.m);print(json.dumps({'run':self.n,'q':p[4:11].tolist(),'eef':p[26:29].tolist(),'fingers':p[11:13].tolist(),'base':p[:4].tolist(),'time_left':self.m['time_left_s']}),flush=True)
 def run(self,c):
  if c['op']=='obs':self.save(self.r.get_obs(include_depth=True,seconds=c.get('seconds',0),video='none'),c);return
  p=pnow(self.m);a=p[29:42].copy();a[8:12]=0;a[12]=-1
  if 'grip' in c:a[7]=c['grip']
  if c['op']=='move':
   q=p[4:11].copy()
   if 'q' in c:q=np.array(c['q'])
   if 'dq' in c:q+=np.array(c['dq'])
   if 'pos' in c:
    q=self.ik(np.array(c['pos']),c.get('rot'),c.get('yaw'))
   count=c.get('steps',50);A=np.tile(a,(count+c.get('hold',12),1));A[:count,:7]=np.linspace(p[4:11],q,count);A[count:,:7]=q
  elif c['op']=='base':
   A=np.tile(a,(c.get('steps',20),1));A[:,8:12]=c.get('vel',[0,0,0,0]);A[:,12]=c.get('mode',1)
  elif c['op']=='grip':A=np.tile(a,(c.get('steps',20),1))
  else:raise ValueError(c)
  self.save(self.r.submit('joint_position',A,cameras=None,include_depth=True,video='none',note=json.dumps(c)),c)
 def pose(self,q):
  t=fk(q);b=self.cal['base'].copy()
  p=pnow(self.m);b[:3,3]+=self.base_displacement(p)
  return b@t@self.cal['tool']
 def base_displacement(self,p):
  # Replaced by calibration after base movement when needed.
  return np.zeros(3)
 def ik(self,pos,rotmat=None,yaw=None):
  q0=pnow(self.m)[4:11];R0=self.pose(q0)[:3,:3]
  if rotmat is not None:R0=np.array(rotmat)
  if yaw is not None:R0=Rotation.from_euler('z',yaw).as_matrix()@np.diag([1,-1,-1])
  def fun(q):
   t=self.pose(q);return np.r_[10*(t[:3,3]-pos),Rotation.from_matrix(R0@t[:3,:3].T).as_rotvec(),.015*(q-q0)]
  lim=([-2.89,-1.76,-2.89,-3.07,-2.89,-.017,-2.89],[2.89,1.76,2.89,-.07,2.89,3.75,2.89])
  sol=least_squares(fun,q0,bounds=lim,max_nfev=250)
  t=self.pose(sol.x);print('IK',sol.x,'position',t[:3,3],'error',np.linalg.norm(t[:3,3]-pos),flush=True)
  if np.linalg.norm(t[:3,3]-pos)>.025:raise ValueError('unreachable target')
  return sol.x

if __name__=='__main__':
 ctl=Control();print('READY',flush=True)
 for line in sys.stdin:
  try:
   c=json.loads(line);ctl.run(c)
  except Exception as e:print(type(e).__name__,str(e),flush=True)
